function loadData(){fetch("data/data.json").then(e=>{if(e.ok)return e.json();throw new Error("Не вдалося завантажити data.json")}).then(e=>{applyPerson(e.person),renderSkills(e.skills),renderExperience(e.jobs)}).catch(e=>{console.error("Помилка:",e)})}function applyPerson(e){var o,t,r,s;e&&(o=document.getElementById("personFirstName"),t=document.getElementById("personLastName"),r=document.getElementById("personRole"),s=document.querySelector(".cv-header__photo"),o&&(o.textContent=e.firstName||""),t&&(t.textContent=e.lastName||""),r&&e.role&&(r.textContent=e.role),s&&e.photo?(s.src=e.photo,s.alt=(`${e.firstName||""} `+(e.lastName||"")).trim(),s.onerror=function(){console.error("Помилка завантаження фото:",e.photo),console.error("Поточний src:",this.src),console.error("Base URL:",window.location.href)},s.onload=function(){console.log("Фото успішно завантажено:",e.photo)}):console.warn("Photo element not found or photo path missing:",{photoEl:s,photo:e?.photo}))}function renderSkills(e){var o=document.getElementById("skillsList");o&&Array.isArray(e)&&(o.innerHTML=e.map(e=>`
      <li class="cv-skill">
        <div class="cv-skill__circle">
          <svg viewBox="0 0 120 120">
            <circle class="bg" cx="60" cy="60" r="50"></circle>
            <circle
              class="progress-border"
              cx="60" cy="60" r="50"
              style="stroke-dasharray: 314;
                     stroke-dashoffset: ${314-e.progress/100*314};
                     transform: rotate(${e.offset}deg);
                     transform-origin: 50% 50%;">
            </circle>
            <circle
              class="progress"
              cx="60" cy="60" r="50"
              style="stroke-dasharray: 314;
                     stroke-dashoffset: ${314-e.progress/100*314};
                     transform: rotate(${e.offset}deg);
                     transform-origin: 50% 50%;">
            </circle>
          </svg>
          <span class="cv-skill__label">${e.name}</span>
        </div>
      </li>`).join(""))}function renderExperience(e){var o=document.getElementById("jobsList");o&&Array.isArray(e)&&(o.innerHTML=e.map(e=>`
      <div class="cv-experience__item">
        <h3>${e.position}</h3>
        <div class="cv-meta">
          <span class="cv-period">${e.period}</span>
          <span class="cv-company">${e.company}</span>
        </div>
        <p class="cv-description">
          ${e.description}
        </p>
      </div>
    `).join(""))}function initToggles(){document.querySelectorAll(".toggle-btn").forEach(o=>{o.addEventListener("click",()=>{var e=o.getAttribute("data-target"),e=document.getElementById(e);e&&(e.classList.toggle("is-hidden"),e=o.querySelector(".toggle-icon"))&&e.classList.toggle("rotated")})})}document.addEventListener("DOMContentLoaded",()=>{initToggles(),loadData()});